select case when duration_sec >= 528 then 'high' when duration_sec >= 144 then 'mid' else 'low' end as duration_sec_bucket, max(duration_sec) as max_duration_sec, count(*) as web_event_count, sum(case when page = '/search' then 1 else 0 end) as search_count from web_events where page = '/search' or duration_sec = 159 group by duration_sec_bucket order by web_event_count, search_count desc;
